create or replace function public.superadmin_verify_qa_remediation(p_remediation_id uuid,p_rerun_id uuid)
returns public.autonomous_qa_remediations language plpgsql security definer set search_path=public,private,auth as $$declare r public.autonomous_qa_remediations%rowtype;rr public.autonomous_qa_runs%rowtype;begin if auth.uid() is null or not private.is_superadmin()then raise exception 'SUPERADMIN_REQUIRED' using errcode='42501';end if;select * into r from public.autonomous_qa_remediations where id=p_remediation_id for update;if r.id is null then raise exception 'REMEDIATION_NOT_FOUND';end if;select * into rr from public.autonomous_qa_runs where id=p_rerun_id and scenario_id=r.scenario_id;if rr.id is null or rr.status<>'PASSED'then raise exception 'PASSING_RERUN_REQUIRED';end if;update public.autonomous_qa_runs set permanent_regression=true where id=rr.id;update public.autonomous_qa_remediations set status='VERIFIED',rerun_id=rr.id,verified_at=now() where id=r.id returning * into r;return r;end$$;
revoke all on function public.superadmin_verify_qa_remediation(uuid,uuid) from public;grant execute on function public.superadmin_verify_qa_remediation(uuid,uuid) to authenticated;